class Solution:

	def possibleWords(self, a, N):
		self.digit_map = {2: 'abc', 3: 'def', 4: 'ghi', 5: 'jkl', 6: 'mno', 7: 'pqrs', 8: 'tuv', 9: 'wxyz'}
		self.ans = []

		def recursion(a, index, ds):
			if index == len(a):
				self.ans.append(ds)
				return
			for ch in self.digit_map[a[index]]:
				recursion(a, index + 1, ds + ch)
		recursion(a, 0, '')
		return self.ans
